CREATE TABLE IF NOT EXISTS contract_versions_v2(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL,version_number INTEGER NOT NULL,version_kind TEXT NOT NULL,document_reference TEXT NOT NULL,document_hash TEXT NOT NULL,execution_certificate_id UUID NOT NULL,status TEXT NOT NULL,supersedes_id UUID REFERENCES contract_versions_v2(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(contract_id,version_number),UNIQUE(workspace_id,document_hash));
CREATE TABLE IF NOT EXISTS contract_analysis_runs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL,contract_version_id UUID NOT NULL REFERENCES contract_versions_v2(id),method TEXT NOT NULL,model_id TEXT,model_version TEXT,prompt_version TEXT,input_hash TEXT NOT NULL,output_hash TEXT NOT NULL,findings JSONB NOT NULL,status TEXT NOT NULL,requested_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contract_analysis_findings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),analysis_run_id UUID NOT NULL REFERENCES contract_analysis_runs(id),finding_type TEXT NOT NULL,severity TEXT NOT NULL,title TEXT NOT NULL,source_references JSONB NOT NULL CHECK(jsonb_array_length(source_references)>0),confidence NUMERIC NOT NULL CHECK(confidence BETWEEN 0 AND 1),review_status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contract_risk_assessments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL,contract_version_id UUID NOT NULL REFERENCES contract_versions_v2(id),analysis_run_id UUID NOT NULL REFERENCES contract_analysis_runs(id),version INTEGER NOT NULL,dimensions JSONB NOT NULL,score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100),level TEXT NOT NULL,explanations JSONB NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(contract_version_id,version));
CREATE TABLE IF NOT EXISTS contract_repository_documents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_version_id UUID NOT NULL REFERENCES contract_versions_v2(id),storage_reference TEXT NOT NULL,content_hash TEXT NOT NULL,mime_type TEXT NOT NULL,classification TEXT NOT NULL,tags JSONB NOT NULL,ocr_text_reference TEXT,legal_hold BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agreement_intelligence_versions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL,contract_version_id UUID NOT NULL REFERENCES contract_versions_v2(id),version INTEGER NOT NULL,items JSONB NOT NULL,status TEXT NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),content_hash TEXT NOT NULL,UNIQUE(contract_id,version));
CREATE TABLE IF NOT EXISTS agreement_intelligence_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),intelligence_version_id UUID NOT NULL REFERENCES agreement_intelligence_versions(id),item_type TEXT NOT NULL,value JSONB NOT NULL,source_references JSONB NOT NULL CHECK(jsonb_array_length(source_references)>0),confidence NUMERIC NOT NULL CHECK(confidence BETWEEN 0 AND 1),review_status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS contract_analysis_version_idx ON contract_analysis_runs(workspace_id,contract_version_id);CREATE INDEX IF NOT EXISTS contract_risk_level_idx ON contract_risk_assessments(workspace_id,level);CREATE INDEX IF NOT EXISTS contract_repository_hash_idx ON contract_repository_documents(workspace_id,content_hash);CREATE INDEX IF NOT EXISTS agreement_intelligence_status_idx ON agreement_intelligence_versions(workspace_id,status);
ALTER TABLE contract_versions_v2 ENABLE ROW LEVEL SECURITY;ALTER TABLE contract_analysis_runs ENABLE ROW LEVEL SECURITY;ALTER TABLE contract_analysis_findings ENABLE ROW LEVEL SECURITY;ALTER TABLE contract_risk_assessments ENABLE ROW LEVEL SECURITY;ALTER TABLE contract_repository_documents ENABLE ROW LEVEL SECURITY;ALTER TABLE agreement_intelligence_versions ENABLE ROW LEVEL SECURITY;ALTER TABLE agreement_intelligence_items ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['contract_versions_v2','contract_analysis_runs','contract_analysis_findings','contract_risk_assessments','contract_repository_documents','agreement_intelligence_versions','agreement_intelligence_items'] LOOP BEGIN EXECUTE format('CREATE POLICY %I ON %I USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id))',t||'_workspace',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['contract_versions_v2','contract_analysis_runs','contract_analysis_findings','contract_risk_assessments','agreement_intelligence_versions','agreement_intelligence_items'] LOOP BEGIN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation()',t||'_append_only',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
